"""Inspect real production-component exports generated by the web integration test.

Set ATS_EXPORT_FIXTURES to the shared directory generated by the paired web test.
Ordinary offline runs skip these two cross-container checks until fixtures are generated.
"""

import json
import os
from pathlib import Path

import pytest

from documents.ats_pdf import inspect_pdf


@pytest.mark.skipif(not os.environ.get("ATS_EXPORT_FIXTURES"), reason="Generate production web exports first")
@pytest.mark.parametrize("name", ["complete", "multipage"])
def test_production_export_retains_saved_content_and_reading_order(name):
    directory = Path(os.environ["ATS_EXPORT_FIXTURES"])
    sections = json.loads((directory / f"{name}.json").read_text())
    result = inspect_pdf((directory / f"{name}.pdf").read_bytes(), sections)
    assert all(check["ratio"] >= 0.98 for check in result["checks"]), result
    if name == "multipage":
        assert result["page_count"] > 1
